(()=>{const update=()=>{const parents=new Set([...document.querySelectorAll('.button')].map(b=>b.parentElement));for(const p of parents){const buttons=[...p.children].filter(b=>b.classList.contains('button'));if(buttons.length<2)continue;p.classList.remove('equal-button-group');p.style.removeProperty('--peer-width');p.style.removeProperty('--peer-height');buttons.forEach(b=>{b.style.removeProperty('width');b.style.removeProperty('min-height')});const w=Math.ceil(Math.max(...buttons.map(b=>b.getBoundingClientRect().width))),h=Math.ceil(Math.max(...buttons.map(b=>b.getBoundingClientRect().height)));p.style.setProperty('--peer-width',w+'px');p.style.setProperty('--peer-height',h+'px');p.classList.add('equal-button-group')}};document.fonts.ready.then(update);window.addEventListener('load',update);let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(update,100)})})();